 ['Matrix Screensaver of the chapter: where the counter is decremented', 'import io, contextlib, random, sys, time\nprog = \'\'\'import random, sys, time\nWIDTH = 70 # The number of columns\ntry:\n    columns = [0] * WIDTH\n    while True:\n        for i in range(WIDTH):\n            if random.random() < 0.02:\n                columns[i] = random.randint(4, 14)\n            if columns[i] == 0:\n                print(\' \', end=\'\')\n            else:\n                print(random.choice([0, 1]), end=\'\')\n                columns[i] -= 1\n        print()\n        time.sleep(0.1)\nexcept KeyboardInterrupt:\n    sys.exit()\n\'\'\'\ndef run(source, rows_wanted):\n    calls = []\n    def fake_sleep(s):\n        calls.append(s)\n        if len(calls) == rows_wanted:\n            raise KeyboardInterrupt\n    time.sleep = fake_sleep\n    random.seed(5)\n    buf = io.StringIO()\n    try:\n        with contextlib.redirect_stdout(buf):\n            exec(source, {})\n    except SystemExit as e:\n        code = e.code\n    rows = buf.getvalue().split(\'\\n\')[:-1]\n    return rows, calls[0], code\nrows, pause, code = run(prog, 300)\nprint(len(rows), {len(r) for r in rows}, set(\'\'.join(rows)) <= set(\' 01\'), pause, code)\nprint(\'streams end:\', rows[-1].count(\' \') > 30)\noutside = prog.replace("                print(random.choice([0, 1]), end=\'\')\\n                columns[i] -= 1\\n", "                print(random.choice([0, 1]), end=\'\')\\n").replace("        print()\\n", "            columns[i] -= 1\\n        print()\\n")\nrows2, pause2, code2 = run(outside, 300)\nprint(\'decrement for every column:\', rows2[-1].count(\' \') < 10, set(\'\'.join(rows2)) <= set(\' 01\'))', '300 {70} True 0.1 None\nstreams end: True\ndecrement for every column: True True'],
