 ['practice program 1 and 2 of the chapter, as one solution', "import random\ndef comma_code(items):\n    if len(items) == 0:\n        return ''\n    if len(items) == 1:\n        return items[0]\n    return ', '.join(items[:-1]) + ', and ' + items[-1]\nprint(repr(comma_code(['apples', 'bananas', 'tofu', 'cats'])), repr(comma_code([])), repr(comma_code(['apples'])))\nrandom.seed(1)\nstreaks = 0\nfor experiment in range(10000):\n    flips = []\n    for i in range(100):\n        flips.append('H' if random.randint(0, 1) == 0 else 'T')\n    for i in range(len(flips) - 5):\n        if flips[i:i + 6] == ['H'] * 6 or flips[i:i + 6] == ['T'] * 6:\n            streaks += 1\n            break\nprint(75 < streaks / 100 < 85)\n# exact probability of six equal flips in a row among 100, by run length\nP = {1: 1.0}\nhit = 0.0\nfor _ in range(99):\n    nxt = {1: 0.0}\n    for r, p in P.items():\n        nxt[1] += p / 2\n        if r + 1 == 6:\n            hit += p / 2\n        else:\n            nxt[r + 1] = nxt.get(r + 1, 0.0) + p / 2\n    P = nxt\nprint(round(hit, 3))\nspam = ['a', 'b', 'c', 'd']\nprint(int(int('3' * 2) // 11), spam[int(int('3' * 2) // 11)])", "'apples, bananas, tofu, and cats' '' 'apples'\nTrue\n0.807\n3 d"],
